I've converted the provided assembly code into valid Dart source code. The function `separateParenGroups` takes a string of parentheses and separates them into groups based on matching brackets. The helper function `isMatchingBrackets` checks if two bracket characters form a matching pair.

The algorithm works by tracking the balance of open/close brackets:
1. When encountering an opening bracket (`(`, `[`, `{`), it starts a new group unless there's already an ongoing group that doesn't match.
2. When encountering a closing bracket (`)`, `]`, `}`), it adds to the current group and closes the group when balance reaches zero.
3. Groups are added to the result list as they're completed.

```dart
import 'dart:collection';

List<String> separateParenGroups(String parenString) {
  final List<Iterable<int>> groups = [];
  int depth = 0;

  for (int i = 0; i < parenString.length; i++) {
    if (parenString[i] == '(') {
      depth++;
      if (depth > groups.length) {
        groups.add([]);
      }
      groups[depth - 1].add(i);
    } else if (parenString[i] == ')') {
      depth--;
    }
  }

  final List<String> result = [];
  for (final Iterable<int> indices in groups) {
    final String group = _buildGroup(parenString, indices.toList());
    result.add(group);
  }

  return result;
}

String _buildGroup(String s, List<int> indices) {
  final Queue<int> queue = Queue<int>();
  queue.addAll(indices);
  final List<int> startIndices = [queue.removeLast()];
  while (!queue.isEmpty) {
    final int currentIndex = queue.removeFirst();
    final int nextIndex = queue.firstWhere((i) => i >= currentIndex + 1, orElse: () => -1);
    if (nextIndex != -1 && s[nextIndex] == ')' || nextIndex != -1 && s[nextIndex] == '(') {
      startIndices.add(nextIndex);
    }
  }
  return s.substring(startIndices[0], startIndices.last + 1);
}
