String? longest(List<String> strings) {
  if (strings.isEmpty || strings == null) return null;

  // Use a queue to process the strings in BFS manner.
  Queue<int> queue = Queue();
  Set<int> visited = Set();
  int maxLenIndex = -1;
  int maxLength = 0;

  // Initialize with index 0 and length of first string.
  queue.add(0);
  visited.add(0);

  while (queue.isNotEmpty) {
    int currentIdx = queue.removeFirst();

    // Check if this is the longest one so far.
    if (strings[currentIdx].length > maxLength) {
      maxLength = strings[currentIdx].length;
      maxLenIndex = currentIdx;
    }

    // Process all neighbors (each character).
    for (int i = 0; i < strings[currentIdx].length; i++) {
      String char = strings[currentIdx][i];

      // Look for other strings that have the same character at position i.
      for (int j = 0; j < strings.length; j++) {
        if (j != currentIdx && !visited.contains(j)) {
          if (i < strings[j].length && strings[j][i] == char) {
            queue.add(j);
            visited.add(j);
          }
        }
      }
    }
  }

  return maxLenIndex >= 0 ? strings[maxLenIndex] : null;
}
