  if (numbers.isEmpty) {
    throw ArgumentError("The input list cannot be empty.");
  }

  // Find the insertion point using binary search
  int insertIndex = numbers.indexWhere((num) => num > target);

  // Handle edge cases where all elements are less than or greater than target
  if (insertIndex == 0) {
    return [numbers[0]]; // All elements are greater than target
  } else if (insertIndex == numbers.length) {
    return [numbers.last]; // All elements are smaller than target
  }

  // Compare the closest candidates
  double leftCandidate = numbers[insertIndex - 1];
  double rightCandidate = numbers[insertIndex];

  // Determine which candidate is closer to the target
  if (abs(leftCandidate - target) <= abs(rightCandidate - target)) {
    return [leftCandidate];
  } else {
    return [rightCandidate];
  }
}
