String antiShuffle(String s) {
  if (s.isEmpty) return '';

  List<String> words = [];
  String currentWord = '';
  for (int i = 0; i < s.length; i++) {
    String char = s[i];
    if (char == ' ') {
      words.add(currentWord);
      currentWord = '';
    } else {
      currentWord += char;
    }
  }
  if (currentWord.isNotEmpty) {
    words.add(currentWord);
  }

  int n = words.length;
  if (n == 0) return '';

  // Calculate the number of possible permutations and find a random one
  int totalPermutations = factorial(n);
  Random rand = Random();
  int permutationIndex = rand.nextInt(totalPermutations);

  // Generate all permutations and select the desired one
  List<List<String>> permutations = generatePermutations(words.toList());
  List<String> selectedPerm = permutations[permutationIndex];

  // Join the permuted words with spaces
  return selectedPerm.join(' ');
}

// Helper function to calculate factorial
int factorial(int n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

// Helper function to generate all permutations of a list
List<List<String>> generatePermutations(List<String> items) {
  if (items.isEmpty) return [[]];
  List<List<String>> result = [];
  for (int i = 0; i < items.length; i++) {
    List<String> remaining = List.from(items)..removeAt(i);
    List<List<String>> subPerms = generatePermutations(remaining);
    for (var perm in subPerms) {
      perm.insert(0, items[i]);
      result.add(perm);
    }
  }
  return result;
}
