  // Calculate the sum of all elements' frequencies that are less than or equal to their index
  int total = 0;
  for (int i = 0; i <= maxVal; i++) {
    if (i >= 0 && i < freq.length && freq[i] > 0) {
      total += min(freq[i], i + 1); // Ensure we don't exceed the actual count
    }
