  Set<int> overfilledPositions = {};
  for (int pos = 0; pos < n; pos++) {
    if (counts[pos] > 1) {
      overfilledPositions.add(pos);
    }
  }

  // If no overfilled positions, return true
  if (overfilledPositions.isEmpty) return true;

  // Check if there's at least one adjacent position that is not full
  bool canMove = false;
  for (var pos in overfilledPositions) {
    // Check left neighbor
    if (pos - 1 >= 0 && counts[pos - 1] < 2) {
      canMove = true;
      break;
    }
    // Check right neighbor
    if (pos + 1 < n && counts[pos + 1] < 2) {
