import 'dart:math';

int maxFill(List<List<int>> grid, int capacity) {
  final rows = grid.length;
  if (rows == 0) return 0;
  final cols = grid[0].length;

  // Directions for up, down, left, right
  final directions = <List<int>>[
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1]
  ];

  var visited = List.generate(rows, (_) => List.filled(cols, false));
  var totalFilled = 0;

  void dfs(int row, int col, int currentCapacity) {
    if (row < 0 || row >= rows || col < 0 || col >= cols || visited[row][col] || currentCapacity <= 0) return;

    visited[row][col] = true;

    // Check if the cell is a wall or has insufficient space
    if (grid[row][col] > currentCapacity) {
      return; // Cannot fill this cell with the given capacity
    }

    // Fill this cell and decrease remaining capacity
    totalFilled += min(grid[row][col], currentCapacity);
    currentCapacity -= grid[row][col];

    // Explore all four directions
    for (var dir in directions) {
      final newRow = row + dir[0];
      final newCol = col + dir[1];
      dfs(newRow, newCol, currentCapacity);
    }
  }

  // Start DFS from each cell that can be filled
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        dfs(r, c, capacity);
      }
    }
  }

  return totalFilled;
}
