import 'dart:math';

List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return [];

  final n = arr.length;
  final result = List<int>.filled(n - k + 1, 0);

  for (int i = 0; i <= n - k; i++) {
    int maxVal = arr[i];
    int index = i;

    // Find the maximum in current window of size k starting at i
