import 'dart:math';

List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  // Helper function to check if a path is valid and compute the minimum sum
  bool isValid(int row, int col, List<int> path, int stepsRemaining) {
    if (row < 0 || row >= rows || col < 0 || col >= cols) return false; // Out of bounds
    if (stepsRemaining == 0) return true; // Reached end with exactly k steps

    for (int i = 0; i < path.length - 1; i++) {
      if (path[i] == row && path[i + 1] == col) {
        // Avoid revisiting the same cell consecutively
        return false;
      }
    }

    // Check adjacent cells (up, right, down, left)
    final directions = [
      [row - 1, col],   // up
      [row, col + 1],   // right
      [row + 1, col],   // down
      [row, col - 1]    // left
    ];

    for (final dir in directions) {
      final nextRow = dir[0];
      final nextCol = dir[1];

      if (!isValid(nextRow, nextCol, [...path, nextRow * cols + nextCol], stepsRemaining - 1)) {
        continue;
      } else {
        return true;
      }
    }

    return false;
  }

  // Start from each possible starting position
  for (var startRow = 0; startRow < rows; startRow++) {
    for (var startCol = 0; startCol < cols; startCol++) {
      var path = [startRow * cols + startCol]; // Starting at this cell
      if (isValid(startRow, startCol, path, k)) {
        // Found a valid path, calculate the total cost
        int totalCost = 0;
        for (int i = 0; i < k; i++) {
          final index = path[i];
          totalCost += grid[index ~/ cols][index % cols];
        }
        return path.map((i) => grid[i ~/ cols][i % cols]).toList();
      }
    }
  }

  return [];
}
