List<String> merge(List<String> left, List<String> right) {
  List<String> result = [];
  int i = 0, j = 0;

  while (i < left.length && j < right.length) {
    String leftVal = left[i];
    String rightVal = right[j];

    // Compare the numeric values of strings as integers
    int leftInt = int.parse(leftVal);
    int rightInt = int.parse(rightVal);

    if (leftInt <= rightInt) {
      result.add(leftVal);
      i++;
    } else {
      result.add(rightVal);
      j++;
    }
  }

  while (i < left.length) {
    result.add(left[i]);
    i++;
  }

  while (j < right.length) {
    result.add(right[j]);
    j++;
  }

  return result;
}
