  // Sort by score descending, then by length of name descending, then alphabetically
  var sortedExtensions = extensionScores.entries.toList()
      .sorted((a, b) {
        final aScore = a.value;
        final bScore = b.value;

        if (aScore != bScore) {
          return bScore - aScore; // Higher scores first
        }
        // If same score, longer names come first
        if (a.key.length != b.key.length) {
          return b.key.length - a.key.length;
        }
        // If same score and same length, alphabetical order
        return a.key.compareTo(b.key);
      });

  return sortedExtensions.first.key;
}

int calculateScore(String extension) {
