  var uniquenessRatio = (distinctCount / maxDistinct) * 100.0;

  var letterCount = extension.replaceAll(RegExp('[^A-Za-z]'), '').length;
  var specialCharCount = extension.length - letterCount;

  var score = 25 + (uniquenessRatio ~/ 1).toInt() + (specialCharCount * 3);
  return score;
}
